// --- Physics (movement + wall/paddle/brick bounces) -------------------------

// Tiny tolerance used to (a) break ties when an overlap is ambiguous and
// (b) absorb floating-point noise in the swept tests, so a ball resting on a
// face does not stutter forever.
const EPS = 1e-6;

// True if the ball is currently overlapping any live brick.
function hitsAnyBrick(ball, bricks) {
  for (const brick of bricks) {
    if (brick.alive && collides(ball, brick)) return true;
  }
  return false;
}

// Resolves the ball's bounce against the bricks it overlaps *right now*.
//
// Per-face rule: among the overlapping bricks we pick the first (seams give a
// shared contact plane, so any of them carries the correct face). The axis
// with the SMALLER penetration is the face that was hit: flip `vy` for a
// top/bottom hit, `vx` for a side hit, both on an equal (corner) hit. The
// untouched component stays exactly as it was.
//
// The velocity is flipped exactly once no matter how many bricks overlap, so
// two bricks touching at a seam do not cancel a bounce (`vy = -vy` twice would
// send the ball straight through). Every overlapped brick is destroyed before
// the single rebound is applied.
//
// Push-out: the ball is repositioned just outside the brick rectangle, so the
// next frame does not see a leftover overlap and flip forever (sticky bounce).
function resolveDiscreteOverlap(state) {
  const { ball, bricks } = state;
  let chosen = null;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      if (!chosen) chosen = brick;
    }
  }
  if (!chosen) return;

  const ox =
    Math.min(ball.x + ball.r, chosen.x + chosen.w) -
    Math.max(ball.x - ball.r, chosen.x);
  const oy =
    Math.min(ball.y + ball.r, chosen.y + chosen.h) -
    Math.max(ball.y - ball.r, chosen.y);
  const cx = chosen.x + chosen.w / 2;
  const cy = chosen.y + chosen.h / 2;

  if (ox < oy - EPS) {
    // Side hit: horizontal faces. Flip vx, keep vy, push out left/right.
    ball.vx = -ball.vx;
    ball.x = ball.x < cx ? chosen.x - ball.r : chosen.x + chosen.w + ball.r;
  } else if (oy < ox - EPS) {
    // Top/bottom hit: vertical faces. Flip vy, keep vx, push out up/down.
    ball.vy = -ball.vy;
    ball.y = ball.y < cy ? chosen.y - ball.r : chosen.y + chosen.h + ball.r;
  } else {
    // Corner: equal penetrations, a diagonal hit. Flip both, nudge out.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x =
      ball.x < cx ? Math.min(ball.x, chosen.x - ball.r) : Math.max(ball.x, chosen.x + chosen.w + ball.r);
    ball.y =
      ball.y < cy ? Math.min(ball.y, chosen.y - ball.r) : Math.max(ball.y, chosen.y + chosen.h + ball.r);
  }
}

// Swept circle vs. an AABB, over the segment the ball travelled this frame.
// Expands the brick by the ball radius (Minkowski sum), then uses the slab
// method to find the earliest time `t` in [0,1] the segment enters the box.
// Returns { t, flipVx, flipVy } describing the entry, or null if it never
// hits. The entry face is the binding slab (the one entered last).
function sweepEntry(x0, y0, dx, dy, r, brick) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  let tNearX, tFarX;
  if (dx === 0) {
    if (x0 < minX || x0 > maxX) return null;
    tNearX = -Infinity;
    tFarX = Infinity;
  } else {
    const t1 = (minX - x0) / dx;
    const t2 = (maxX - x0) / dx;
    tNearX = Math.min(t1, t2);
    tFarX = Math.max(t1, t2);
  }

  let tNearY, tFarY;
  if (dy === 0) {
    if (y0 < minY || y0 > maxY) return null;
    tNearY = -Infinity;
    tFarY = Infinity;
  } else {
    const t1 = (minY - y0) / dy;
    const t2 = (maxY - y0) / dy;
    tNearY = Math.min(t1, t2);
    tFarY = Math.max(t1, t2);
  }

  const tEnter = Math.max(tNearX, tNearY);
  const tExit = Math.min(tFarX, tFarY);
  if (tEnter > tExit + EPS) return null;

  let flipVx = false;
  let flipVy = false;
  if (tNearX > tNearY + EPS) {
    flipVx = true;
  } else if (tNearY > tNearX + EPS) {
    flipVy = true;
  } else {
    flipVx = true;
    flipVy = true; // corner entry
  }

  return { t: tEnter, flipVx, flipVy };
}

// Catches the tunnelling case: detection is discrete, so a fast ball can jump
// clean past a brick between two frames without ever overlapping it. This
// sweeps the segment from the previous position to the current one, finds the
// earliest brick crossed, and reflects the ball at the exact entry point.
function resolveSweep(state, prevX, prevY) {
  const { ball, bricks } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let best = Infinity;
  let hitIndex = -1;
  let flipVx = false;
  let flipVy = false;
  for (let i = 0; i < bricks.length; i++) {
    const brick = bricks[i];
    if (!brick.alive) continue;
    const hit = sweepEntry(prevX, prevY, dx, dy, ball.r, brick);
    if (hit && hit.t < best) {
      best = hit.t;
      hitIndex = i;
      flipVx = hit.flipVx;
      flipVy = hit.flipVy;
    }
  }
  if (hitIndex === -1 || best > 1 + EPS) return;

  const brick = bricks[hitIndex];
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  const t = Math.max(0, Math.min(1, best));
  ball.x = prevX + dx * t;
  ball.y = prevY + dy * t;
  if (flipVx) ball.vx = -ball.vx;
  if (flipVy) ball.vy = -ball.vy;
}

// Full ball-vs-brick collision resolution for one time step.
//
// If the ball ends the step overlapping a brick we use the discrete,
// penetration-based resolve (it covers ordinary hits and sticky cleanups).
// Otherwise the ball flew clear of every brick this frame, so we sweep between
// the previous and current positions to catch high-speed tunnelling.
function resolveBrickCollisions(state, prevX, prevY) {
  if (hitsAnyBrick(state.ball, state.bricks)) {
