  step(state, 0);
  assert.equal(state.ball.vx, -200);
  assert.equal(state.ball.vy, 200);
  assert.equal(state.bricks[0].alive, false);
});

test('brick: overlapping two bricks at a seam flips once, not twice', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 100, w: 72, h: 20, alive: true, points: 10 },
    { x: 180, y: 100, w: 72, h: 20, alive: true, points: 10 },
  ];
  state.ball = { x: 176, y: 110, r: 7, vx: 200, vy: 0 };
  step(state, 0);
  assert.equal(
    state.ball.vx,
    -200,
    'vx must be flipped once: two flips in the same pass would cancel out',
  );
  assert.equal(state.ball.vy, 0);
  assert.equal(state.bricks[0].alive, false);
  assert.equal(state.bricks[1].alive, false);
});

test('brick: fast ball that jumps clear past a brick still bounces (tunnelling)', () => {
  const state = stateWithBrick({ x: 300, y: 100, w: 72, h: 20 });
